import 'package:swiss_knife/swiss_knife.dart';

class User {
  final EventStream<String> onNotification = new EventStream();

  void notify(String msg) {
    onNotification.add(msg);
  }
}

void main() {
  User user = new User();
  user.onNotification.listen((msg) {
    print("NOTIFICATION> $msg");
  });
}
